{"implementation":"def solve(case):
    from fractions import Fraction

    segments = case["segments"]
    capacities = [max(0, int(segment["capacity"])) for segment in segments]
    minimums = [
        min(capacities[i], max(0, int(segment["minimum"])))
        for i, segment in enumerate(segments)
    ]
    weights = [max(0, int(segment["importance"])) for segment in segments]
    target = min(max(0, int(case["budget"])), sum(capacities))

    if target >= sum(minimums):
        allocations = minimums[:]
        remaining = target - sum(allocations)
        limits = capacities
    else:
        allocations = [0] * len(segments)
        remaining = target
        limits = minimums

    active = {i for i in range(len(segments)) if allocations[i] < limits[i]}

    while remaining > 0 and active:
        total_weight = sum(weights[i] for i in active)
        effective_weights = {
            i: (weights[i] if total_weight > 0 else 1) for i in active
        }
        total_effective_weight = sum(effective_weights.values())

        saturated = []
        for i in active:
            room = limits[i] - allocations[i]
            share = Fraction(remaining * effective_weights[i], total_effective_weight)
            if share >= room:
                saturated.append(i)

        if saturated:
            for i in saturated:
                room = limits[i] - allocations[i]
                allocations[i] += room
                remaining -= room
                active.remove(i)
            continue

        shares = {
            i: Fraction(remaining * effective_weights[i], total_effective_weight)
            for i in active
        }
        for i in active:
            amount = shares[i].numerator // shares[i].denominator
            allocations[i] += amount
            remaining -= amount

        order = sorted(
            active,
            key=lambda i: (-(shares[i] - (shares[i].numerator // shares[i].denominator)), i),
        )
        for i in order:
            if remaining == 0:
                break
            if allocations[i] < limits[i]:
                allocations[i] += 1
                remaining -= 1
        break

    by_name = {
        segment["name"]: allocations[i]
        for i, segment in enumerate(segments)
    }
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": sum(allocations),
    }
"}
